package vn.aicrm.retail;

import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import vn.coreplatform.audit.AuditService;
import static vn.aicrm.retail.RetailAccess.*;

@RestController
@RequestMapping("/api/v1/retail/permissions")
public class RetailPermissionController {
  private final RetailAccess r;private final RetailPermissions p;private final AuditService audit;
  public RetailPermissionController(RetailAccess r,RetailPermissions p,AuditService audit){this.r=r;this.p=p;this.audit=audit;}
  private void admin(Authentication a){r.permissions.require(a,"ACCESS_ADMIN","MANAGE",null);}
  @GetMapping("/capabilities") Object capabilities(Authentication a){r.require(a,"READ");return p.capabilities(a);}
  @GetMapping Object catalog(Authentication a){admin(a);return Map.of("features",RetailPermissions.FEATURES,"templates",templates(),"warehouses",r.warehouses(a),"roles",r.db.queryForList("select id,code,name,system_role from identity.role where tenant_id=? order by name",r.tenant(a)),"users",r.db.queryForList("select id,email,display_name from identity.account where tenant_id=? and enabled order by display_name",r.tenant(a)));}
  private Map<String,Map<String,List<String>>> templates(){return Map.of(
    "sales",Map.of("pos",List.of("VIEW","CREATE","SUBMIT","PRINT"),"orders",List.of("VIEW","CREATE","SUBMIT","PRINT"),"customer",List.of("VIEW","CREATE"),"delivery",List.of("VIEW","CREATE","UPDATE")),
    "cashier",Map.of("pos",List.of("VIEW","COLLECT_POS"),"orders",List.of("VIEW"),"receipt",List.of("VIEW","CREATE","ALLOCATE","PRINT"),"receivables",List.of("VIEW","ALLOCATE")),
    "warehouse",Map.of("stock",List.of("VIEW","RECEIVE","DISPATCH"),"issue",List.of("VIEW","CREATE","SUBMIT"),"transfer",List.of("VIEW","CREATE","SUBMIT","DISPATCH","RECEIVE"),"count",List.of("VIEW","CREATE","UPDATE","SUBMIT")),
    "buyer",Map.of("purchase-order",List.of("VIEW","CREATE","SUBMIT","PRINT"),"purchase-receipt",List.of("VIEW","CREATE","SUBMIT","PRINT"),"purchase-return",List.of("VIEW","CREATE","SUBMIT"),"supplier",List.of("VIEW","CREATE","UPDATE")),
    "care",Map.of("customer",List.of("VIEW","CREATE","UPDATE"),"crm",List.of("VIEW","CREATE","UPDATE","COMPLETE","VIEW_HISTORY"),"warranty",List.of("VIEW","CREATE","UPDATE","LOOKUP_ORIGINAL")),
    "accountant",Map.of("receipt",List.of("VIEW","CREATE","ALLOCATE","PRINT"),"payment",List.of("VIEW","CREATE","ALLOCATE","PRINT"),"receivables",List.of("VIEW","ALLOCATE","EXPORT"),"payables",List.of("VIEW","ALLOCATE","EXPORT"),"partners",List.of("VIEW","VIEW_BANK","UPDATE_BANK"),"sensitive",List.of("VIEW","VIEW_COST"),"report-finance",List.of("VIEW","EXPORT")),
    "branch-manager",Map.of("orders",List.of("VIEW","CREATE","SUBMIT","APPROVE","REJECT"),"purchase-order",List.of("VIEW","APPROVE","REJECT"),"purchase-receipt",List.of("VIEW","APPROVE","REJECT","CONFIRM_DISCREPANCY"),"stock",List.of("VIEW","APPROVE","REJECT"),"count",List.of("VIEW","APPROVE","REJECT"),"transfer",List.of("VIEW","APPROVE","REJECT"),"customer",List.of("VIEW"),"supplier",List.of("VIEW")));
  }
  @PostMapping("/roles") @Transactional public Object createRole(Authentication a,@RequestBody JsonNode x){admin(a);String code=required(x,"code",100),name=required(x,"name",160);required(x,"reason",1000);if(!code.matches("[a-z][a-z0-9-]{2,99}"))throw problem("INVALID_ROLE","Mã vai trò cần 3–100 ký tự: chữ thường, số và dấu gạch ngang; bắt đầu bằng chữ.");var t=r.tenant(a);if(r.db.queryForObject("select count(*) from identity.role where tenant_id=? and code=?",Integer.class,t,code)>0)throw problem("ROLE_EXISTS","Mã vai trò đã có");UUID id=UUID.randomUUID();r.db.update("insert into identity.role(id,tenant_id,code,name) values(?,?,?,?)",id,t,code,name);var body=(com.fasterxml.jackson.databind.node.ObjectNode)x.deepCopy();body.put("revision",r.db.queryForObject("select revision from identity.permission_revision where tenant_id=?",Long.class,t));save(a,id,body);var result=new LinkedHashMap<String,Object>((Map<String,Object>)role(a,id));result.put("id",id);return result;}
  @PostMapping("/template") @Transactional public Object createTemplate(Authentication a,@RequestBody JsonNode x){admin(a);String template=required(x,"template",60);var preset=templates().get(template);if(preset==null)throw problem("INVALID_TEMPLATE","Vai trò mẫu không hợp lệ");String code=required(x,"code",100),name=required(x,"name",160),reason=required(x,"reason",1000);if(!code.matches("[a-z][a-z0-9-]{2,99}"))throw problem("INVALID_ROLE","Mã vai trò không hợp lệ");var t=r.tenant(a);if(r.db.queryForObject("select count(*) from identity.role where tenant_id=? and code=?",Integer.class,t,code)>0)throw problem("ROLE_EXISTS","Mã vai trò đã có");UUID id=UUID.randomUUID();r.db.update("insert into identity.role(id,tenant_id,code,name) values(?,?,?,?)",id,t,code,name);var body=r.json.createObjectNode().put("reason",reason).put("revision",r.db.queryForObject("select revision from identity.permission_revision where tenant_id=?",Long.class,t));var grants=body.putArray("grants");preset.forEach((feature,actions)->actions.forEach(action->grants.addObject().put("feature",feature).put("action",action).put("effect","ALLOW")));save(a,id,body);return Map.of("id",id,"name",name,"code",code);}
  @GetMapping("/roles/{id}") Object role(Authentication a,@PathVariable UUID id){admin(a);var t=r.tenant(a);if(r.db.queryForObject("select count(*) from identity.role where id=? and tenant_id=?",Integer.class,id,t)==0)throw problem("NOT_FOUND","Vai trò không tồn tại",HttpStatus.NOT_FOUND);var roleRow=r.db.queryForMap("select * from identity.role where tenant_id=? and id=?",t,id);return Map.of("editable",editBlock(a,id,roleRow).isEmpty(),"editBlockReason",editBlock(a,id,roleRow),"policies",r.db.queryForList("select p.id,p.resource_type,p.action,p.effect,p.condition_json,p.code from identity.role_policy rp join identity.policy p on p.tenant_id=rp.tenant_id and p.id=rp.policy_id where rp.tenant_id=? and rp.role_id=? and p.enabled",t,id),"revision",r.db.queryForObject("select revision from identity.permission_revision where tenant_id=?",Long.class,t));}
  @GetMapping("/users/{id}/preview") Object preview(Authentication a,@PathVariable UUID id){admin(a);var t=r.tenant(a);var user=r.db.queryForList("select id,email from identity.account where tenant_id=? and id=?",t,id);if(user.isEmpty())throw problem("NOT_FOUND","Tài khoản không tồn tại",HttpStatus.NOT_FOUND);var auth=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(user.getFirst().get("email"),null,List.of());auth.setDetails(Map.of("tenantId",t,"accountId",id));return Map.of("revision",r.db.queryForObject("select revision from identity.permission_revision where tenant_id=?",Long.class,t),"capabilities",p.capabilities(auth),"scopes",r.db.queryForList("select s.warehouse_id,w.name warehouse,s.branch_id from retail.access_scope s join retail.warehouse w on w.tenant_id=s.tenant_id and w.id=s.warehouse_id where s.tenant_id=? and s.account_id=?",t,id),"allBranches",r.all(auth),"roleIds",r.db.queryForList("select role_id from identity.account_role where tenant_id=? and account_id=?",t,id).stream().map(row->row.get("role_id")).toList(),"sources",r.db.queryForList("select rl.name role,p.resource_type,p.action,p.effect,p.condition_json from identity.account_role ar join identity.role rl on rl.tenant_id=ar.tenant_id and rl.id=ar.role_id join identity.role_policy rp on rp.tenant_id=rl.tenant_id and rp.role_id=rl.id join identity.policy p on p.tenant_id=rp.tenant_id and p.id=rp.policy_id where ar.tenant_id=? and ar.account_id=? and p.enabled",t,id));}
  @PostMapping("/users/{id}/roles") @Transactional public Object userRoles(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x){admin(a);var t=r.tenant(a);String reason=required(x,"reason",1000);if(id.equals(r.actor(a)))throw problem("SELF_PERMISSION_CHANGE","Không thay đổi vai trò của chính mình",HttpStatus.FORBIDDEN);if(r.db.queryForObject("select count(*) from identity.account where tenant_id=? and id=?",Integer.class,t,id)==0)throw problem("NOT_FOUND","Người dùng không tồn tại",HttpStatus.NOT_FOUND);var rev=r.db.queryForObject("select revision from identity.permission_revision where tenant_id=? for update",Long.class,t);if(x.path("revision").asLong(-1)!=rev)throw problem("VERSION_CONFLICT","Phân quyền đã thay đổi; tải lại",HttpStatus.CONFLICT);if(!x.path("roleIds").isArray())throw problem("INVALID_ROLE","Chọn danh sách vai trò");var ids=new HashSet<UUID>();for(var value:x.path("roleIds")){UUID role;try{role=UUID.fromString(value.asText());}catch(Exception e){throw problem("INVALID_ROLE","Mã vai trò không hợp lệ");}if(r.db.queryForObject("select count(*) from identity.role where tenant_id=? and id=?",Integer.class,t,role)==0)throw problem("INVALID_ROLE","Vai trò không thuộc công ty");ids.add(role);}var before=r.db.queryForList("select role_id from identity.account_role where tenant_id=? and account_id=?",t,id);r.db.update("delete from identity.account_role where tenant_id=? and account_id=?",t,id);for(UUID role:ids)r.db.update("insert into identity.account_role(tenant_id,account_id,role_id) values(?,?,?)",t,id,role);r.db.update("update identity.permission_revision set revision=revision+1,updated_at=now() where tenant_id=?",t);audit.record(r.permissions.tenantKey(a),r.actor(a),a.getName(),"RETAIL_USER_ROLES_CHANGE","ACCESS_ADMIN",id.toString(),"SUCCESS",r.json.valueToTree(Map.of("reason",reason,"before",before,"after",ids)).toString());return preview(a,id);}
  @PostMapping("/users/{id}/scopes") @Transactional public Object scopes(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x){admin(a);p.require(a,"scope","MANAGE");var t=r.tenant(a);required(x,"reason",1000);if(id.equals(r.actor(a)))throw problem("SELF_PERMISSION_CHANGE","Không sửa phạm vi của chính mình",HttpStatus.FORBIDDEN);if(r.db.queryForObject("select count(*) from identity.account where tenant_id=? and id=?",Integer.class,t,id)==0)throw problem("NOT_FOUND","Người dùng không tồn tại",HttpStatus.NOT_FOUND);var revision=r.db.queryForObject("select revision from identity.permission_revision where tenant_id=? for update",Long.class,t);if(x.path("revision").asLong(-1)!=revision)throw problem("VERSION_CONFLICT","Phân quyền đã thay đổi; tải lại",HttpStatus.CONFLICT);if(!x.path("warehouseIds").isArray())throw problem("INVALID_SCOPE","Chọn danh sách kho");var ids=new HashSet<UUID>();for(var item:x.path("warehouseIds")){UUID warehouse;try{warehouse=UUID.fromString(item.asText());}catch(Exception e){throw problem("INVALID_SCOPE","Mã kho không hợp lệ");}r.warehouse(a,warehouse);ids.add(warehouse);}var before=r.db.queryForList("select warehouse_id from retail.access_scope where tenant_id=? and account_id=?",t,id);r.db.update("delete from retail.access_scope where tenant_id=? and account_id=?",t,id);for(UUID warehouse:ids){var w=r.one("warehouse",t,warehouse);r.db.update("insert into retail.access_scope(tenant_id,account_id,branch_id,warehouse_id) values(?,?,?,?)",t,id,w.get("branch_id"),warehouse);}r.db.update("update identity.permission_revision set revision=revision+1,updated_at=now() where tenant_id=?",t);audit.record(r.permissions.tenantKey(a),r.actor(a),a.getName(),"RETAIL_SCOPE_CHANGE","ACCESS_ADMIN",id.toString(),"SUCCESS",r.json.valueToTree(Map.of("before",before,"after",ids,"reason",x.path("reason"))).toString());return preview(a,id);}
  private String editBlock(Authentication a,UUID id,Map<String,Object> role){if(Boolean.TRUE.equals(role.get("system_role"))&&!"application-user".equals(role.get("code")))return "Vai trò quản trị hệ thống được bảo vệ; hãy chọn Application User hoặc tạo vai trò nghiệp vụ để phân quyền.";if(r.db.queryForObject("select count(*) from identity.account_role where tenant_id=? and account_id=? and role_id=?",Integer.class,r.tenant(a),r.actor(a),id)>0)return "Không sửa vai trò đang gán cho chính mình. Hãy dùng một tài khoản quản trị khác để điều chỉnh.";return "";}
  @PostMapping("/roles/{id}") @Transactional public Object save(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x){admin(a);var t=r.tenant(a);String reason=required(x,"reason",1000);var rows=r.db.queryForList("select * from identity.role where tenant_id=? and id=? for update",t,id);if(rows.isEmpty())throw problem("NOT_FOUND","Vai trò không tồn tại",HttpStatus.NOT_FOUND);String block=editBlock(a,id,rows.getFirst());if(!block.isEmpty())throw problem("ROLE_READ_ONLY",block,HttpStatus.FORBIDDEN);
    var revision=r.db.queryForObject("select revision from identity.permission_revision where tenant_id=? for update",Long.class,t);if(x.path("revision").asLong(-1)!=revision)throw problem("VERSION_CONFLICT","Phân quyền đã thay đổi; tải lại trước khi lưu",HttpStatus.CONFLICT);
    if(!x.path("grants").isArray()||x.path("grants").size()>600)throw problem("INVALID_PERMISSION","Danh sách quyền không hợp lệ");var seen=new HashSet<String>();for(var g:x.path("grants")){String code=required(g,"feature",80),action=required(g,"action",40),effect=text(g,"effect","ALLOW");var f=RetailPermissions.FEATURES.stream().filter(v->v.code().equals(code)).findFirst().orElseThrow(()->problem("INVALID_PERMISSION","Chức năng không hợp lệ"));if(!f.actions().contains(action)||!Set.of("ALLOW","DENY").contains(effect)||!seen.add(code+":"+action))throw problem("INVALID_PERMISSION","Quyền không hợp lệ hoặc trùng");}
    for(var g:x.path("grants"))if(!g.path("action").asText().equals("VIEW")&&text(g,"effect","ALLOW").equals("ALLOW")){String code=g.path("feature").asText();boolean view=false;for(var v:x.path("grants"))if(v.path("feature").asText().equals(code)&&v.path("action").asText().equals("VIEW")&&text(v,"effect","ALLOW").equals("ALLOW"))view=true;if(!view)throw problem("PERMISSION_DEPENDENCY","Cần quyền Xem trước khi cấp thao tác tại "+code);}
    var before=role(a,id);r.db.update("delete from identity.role_policy rp using identity.policy p where rp.tenant_id=? and rp.role_id=? and p.tenant_id=rp.tenant_id and p.id=rp.policy_id and p.code like 'retail-module-%'",t,id);
    for(var g:x.path("grants")){String feature=g.path("feature").asText(),action=g.path("action").asText(),effect=text(g,"effect","ALLOW");String code="retail-module-"+feature+"-"+action.toLowerCase(Locale.ROOT)+"-"+effect.toLowerCase(Locale.ROOT);var found=r.db.queryForList("select id from identity.policy where tenant_id=? and code=?",t,code);UUID policy=found.isEmpty()?UUID.randomUUID():(UUID)found.getFirst().get("id");if(found.isEmpty())r.db.update("insert into identity.policy(id,tenant_id,code,resource_type,action,effect,condition_json) values(?,?,?,?,?,?,?::jsonb)",policy,t,code,RetailPermissions.resource(feature),action,effect,"{}");r.db.update("insert into identity.role_policy(tenant_id,role_id,policy_id) values(?,?,?) on conflict do nothing",t,id,policy);}
    r.db.update("update identity.permission_revision set revision=revision+1,updated_at=now() where tenant_id=?",t);audit.record(r.permissions.tenantKey(a),r.actor(a),a.getName(),"RETAIL_PERMISSION_CHANGE","ACCESS_ADMIN",id.toString(),"SUCCESS",r.json.valueToTree(Map.of("reason",reason,"before",before,"after",x.path("grants"))).toString());return role(a,id);
  }
}
